O resultado da execução do código a seguir, escrito em Java,
será SubA.
abstract class FuncaoA {
FuncaoA() {
this(null);
System.out.print(“FuncaoA”);
}
FuncaoA(SubA s) { this.init(); }
abstract void init();
}
class SubA extends FuncaoA {
void init() { System.out.print(“SubA”); }
public static void main (String[] arg) {
SubA a = new SubA(); }
}
